insert into public.bands
  (id, slug, name, city, genres, occasions, description, notable_performances, members_count, rating, featured, price_per_event, price_breakdown, booked, reviews)
values
  ('8a2f1b10-0001-4a3e-9c2d-1a2b3c4d5e01', 'sitara', 'Sitara Sound Collective', 'Delhi NCR', ARRAY['bollywood']::text[], ARRAY[]::text[], '10-piece live band · Hindi, Punjabi, retro', null, 10, 4.5, false, 145000, '{"performance":145000,"extraHour":22000,"sound":"included","travelCity":0,"outstation":18000,"earlySetup":8000,"dj":25000,"advancePct":40,"refundDays":45,"contract":true}'::jsonb, ARRAY['2026-11-21', '2026-12-05', '2026-12-12']::date[], '[{"author":"Ritika S.","date":"Feb 2026","text":"Arrived at 4pm for a 7pm start, sound check done well before guests came in. Played the full three hours we booked.","reliability":"specific","flag":null},{"author":"Aman & Nidhi","date":"Jan 2026","text":"Same ten musicians we met at the audition turned up on the day. That mattered more to us than anything.","reliability":"specific","flag":null},{"author":"Harpreet K.","date":"Dec 2025","text":"Set list was a bit safe for our crowd, we wanted more Punjabi folk. But they were exactly on schedule.","reliability":"specific","flag":null},{"author":"Devansh M.","date":"Dec 2025","text":"Great energy, the brass section was the highlight of the sangeet.","reliability":"none","flag":null},{"author":"Sunita R.","date":"Nov 2025","text":"Stayed 20 minutes past the end because the pheras ran late. No fuss, no extra charge.","reliability":"specific","flag":null},{"author":"Kabir J.","date":"Nov 2025","text":"Sound engineer knew the venue already so setup was quick.","reliability":"specific","flag":null},{"author":"Meghna T.","date":"Oct 2025","text":"Loved them. Everyone asked who we booked.","reliability":"none","flag":null},{"author":"Arjun P.","date":"Sep 2025","text":"Priced higher than the others we shortlisted, worth it in the end.","reliability":"none","flag":null},{"author":"Farida Q.","date":"Aug 2025","text":"Vocalist was ill and they told us four days ahead, sent a replacement recording to approve first. Handled properly.","reliability":"specific","flag":null}]'::jsonb),
  ('8a2f1b10-0002-4a3e-9c2d-1a2b3c4d5e02', 'marigold', 'The Marigold Brass Co.', 'Delhi NCR', ARRAY['brass']::text[], ARRAY[]::text[], '14-piece baraat brass · processional, dhol', null, 14, 4.5, false, 98000, '{"performance":98000,"extraHour":15000,"sound":20000,"travelCity":6000,"outstation":24000,"earlySetup":null,"dj":null,"advancePct":60,"refundDays":0,"contract":false}'::jsonb, ARRAY['2026-12-05']::date[], '[{"author":"Nikhil B.","date":"Mar 2026","text":"Best baraat entry on our street in years. The dhol players were unreal.","reliability":"none","flag":null},{"author":"Preeti A.","date":"Feb 2026","text":"Twelve of the fourteen musicians we were shown did not turn up. They sent juniors instead and would not adjust the price. Our 60% advance was already paid and they refused to return any of it.","reliability":"negative","flag":"substitution"},{"author":"Rohan D.","date":"Feb 2026","text":"Loud, fun, exactly the vibe we wanted for the procession.","reliability":"none","flag":null},{"author":"Simran V.","date":"Jan 2026","text":"Good value compared to quotes we got elsewhere.","reliability":"none","flag":null},{"author":"Tarun G.","date":"Jan 2026","text":"On time and set up quickly.","reliability":"specific","flag":null},{"author":"Ishita M.","date":"Dec 2025","text":"Everyone danced. Would recommend for a baraat.","reliability":"none","flag":null},{"author":"Yash K.","date":"Dec 2025","text":"Really strong performers.","reliability":"none","flag":null},{"author":"Anita L.","date":"Nov 2025","text":"The trumpet solo was lovely.","reliability":"none","flag":null},{"author":"Vikram S.","date":"Nov 2025","text":"Turned up on schedule, played the full route.","reliability":"specific","flag":null},{"author":"Neha C.","date":"Oct 2025","text":"Great for the money.","reliability":"none","flag":null},{"author":"Gaurav T.","date":"Oct 2025","text":"Fantastic energy, five stars.","reliability":"none","flag":null},{"author":"Pooja N.","date":"Sep 2025","text":"Booking over WhatsApp was easy, no paperwork though.","reliability":"none","flag":null}]'::jsonb),
  ('8a2f1b10-0003-4a3e-9c2d-1a2b3c4d5e03', 'anhad', 'Anhad Live', 'Jaipur', ARRAY['sufi']::text[], ARRAY[]::text[], '6-piece live band · Sufi, ghazal, acoustic', null, 6, 4.5, false, 72000, '{"performance":72000,"extraHour":12000,"sound":14000,"travelCity":3000,"outstation":15000,"earlySetup":5000,"dj":null,"advancePct":30,"refundDays":30,"contract":true}'::jsonb, ARRAY[]::date[], '[{"author":"Shalini M.","date":"Apr 2026","text":"Beautiful voices. Our mehndi felt like a private concert.","reliability":"none","flag":null},{"author":"Ayaan R.","date":"Mar 2026","text":"New band but very professional with us over email.","reliability":"none","flag":null},{"author":"Divya K.","date":"Feb 2026","text":"Lovely set, would book again.","reliability":"none","flag":null}]'::jsonb),
  ('8a2f1b10-0004-4a3e-9c2d-1a2b3c4d5e04', 'baaraat', 'Baaraat Beats Bandwalla', 'Delhi NCR', ARRAY['brass', 'bollywood', 'bhangra']::text[], ARRAY[]::text[], '12-piece band + brass · Bollywood, bhangra', null, 12, 4.5, false, 112000, '{"performance":112000,"extraHour":18000,"sound":"included","travelCity":4000,"outstation":20000,"earlySetup":6000,"dj":18000,"advancePct":50,"refundDays":21,"contract":true}'::jsonb, ARRAY['2026-11-21', '2026-11-28']::date[], '[{"author":"Manav S.","date":"Mar 2026","text":"Turned up 90 minutes late. The mandap was ready and guests were seated with nothing happening.","reliability":"negative","flag":null},{"author":"Ekta B.","date":"Mar 2026","text":"On time, set up early, played right through.","reliability":"specific","flag":null},{"author":"Rahul V.","date":"Feb 2026","text":"Arrived when they said they would. No issues at all.","reliability":"specific","flag":null},{"author":"Jyoti P.","date":"Feb 2026","text":"They were late for the sangeet but made up for it by playing an extra half hour.","reliability":"negative","flag":null},{"author":"Amitav N.","date":"Jan 2026","text":"Musicians were excellent, crowd loved it.","reliability":"none","flag":null},{"author":"Sneha R.","date":"Jan 2026","text":"Two of the singers were different from the ones we auditioned. They did tell us a week before.","reliability":"negative","flag":null},{"author":"Kunal M.","date":"Dec 2025","text":"Solid band, good song range.","reliability":"none","flag":null},{"author":"Ridhi T.","date":"Dec 2025","text":"Punctual and easy to coordinate with our planner.","reliability":"specific","flag":null}]'::jsonb),
  ('8a2f1b10-0005-4a3e-9c2d-1a2b3c4d5e05', 'nauras', 'Nauras Ensemble', 'Mumbai', ARRAY['bollywood', 'jazz']::text[], ARRAY[]::text[], '8-piece live band · jazz, retro Bollywood', null, 8, 4.5, false, 165000, '{"performance":165000,"extraHour":26000,"sound":"included","travelCity":0,"outstation":30000,"earlySetup":"included","dj":30000,"advancePct":35,"refundDays":60,"contract":true}'::jsonb, ARRAY['2026-12-12']::date[], '[{"author":"Farhan A.","date":"Apr 2026","text":"Load-in three hours early, full sound check, started on the minute.","reliability":"specific","flag":null},{"author":"Tanvi D.","date":"Mar 2026","text":"Exactly the line-up in the contract, all eight of them.","reliability":"specific","flag":null},{"author":"Zoya H.","date":"Mar 2026","text":"The saxophonist alone was worth the fee.","reliability":"none","flag":null},{"author":"Nitin K.","date":"Feb 2026","text":"Monsoon shifted our venue indoors two days before and they re-planned the setup without complaint or extra cost.","reliability":"specific","flag":null},{"author":"Aditi J.","date":"Feb 2026","text":"Expensive, but nothing went wrong all evening.","reliability":"specific","flag":null},{"author":"Rushil B.","date":"Jan 2026","text":"Very polished. Our older guests loved the retro set.","reliability":"none","flag":null},{"author":"Leena M.","date":"Dec 2025","text":"Played the booked set list, finished on time, packed down quietly during dinner.","reliability":"specific","flag":null}]'::jsonb),
  ('8a2f1b10-0006-4a3e-9c2d-1a2b3c4d5e06', 'rangeen', 'Rangeen Roadshow', 'Chandigarh', ARRAY['bhangra']::text[], ARRAY[]::text[], '9-piece band · pop, bhangra, DJ hybrid', null, 9, 4.5, false, 88000, '{"performance":88000,"extraHour":14000,"sound":16000,"travelCity":5000,"outstation":17000,"earlySetup":null,"dj":14000,"advancePct":50,"refundDays":15,"contract":true}'::jsonb, ARRAY[]::date[], '[{"author":"Gurpreet S.","date":"Apr 2026","text":"Dance floor was full from the first song.","reliability":"none","flag":null},{"author":"Meera K.","date":"Mar 2026","text":"Song selection was perfect for a mixed-age crowd.","reliability":"none","flag":null},{"author":"Vivek T.","date":"Mar 2026","text":"Good sound quality, decent lights.","reliability":"none","flag":null},{"author":"Anjali R.","date":"Feb 2026","text":"Five stars, so much fun.","reliability":"none","flag":null},{"author":"Sahil M.","date":"Feb 2026","text":"Slightly pricey for Chandigarh but they delivered a good show.","reliability":"none","flag":null},{"author":"Kirti B.","date":"Jan 2026","text":"Loved the bhangra medley.","reliability":"none","flag":null},{"author":"Deepak N.","date":"Jan 2026","text":"Nice people to deal with.","reliability":"none","flag":null},{"author":"Ruchi A.","date":"Dec 2025","text":"Great atmosphere at the reception.","reliability":"none","flag":null},{"author":"Ashwin P.","date":"Dec 2025","text":"Would recommend to friends.","reliability":"none","flag":null},{"author":"Nisha V.","date":"Nov 2025","text":"Really enjoyed the evening.","reliability":"none","flag":null},{"author":"Tejas L.","date":"Nov 2025","text":"Good band, good energy.","reliability":"none","flag":null}]'::jsonb),
  ('8a2f1b10-0007-4a3e-9c2d-1a2b3c4d5e07', 'qissa', 'Qissa Qawwali Party', 'Lucknow', ARRAY['sufi']::text[], ARRAY[]::text[], '7-piece qawwali party · traditional', null, 7, 4.5, false, 64000, '{"performance":64000,"extraHour":10000,"sound":12000,"travelCity":2500,"outstation":14000,"earlySetup":null,"dj":null,"advancePct":25,"refundDays":30,"contract":false}'::jsonb, ARRAY[]::date[], '[{"author":"Sadia F.","date":"Mar 2026","text":"Moving performance, the whole family was in tears by the end.","reliability":"none","flag":null},{"author":"Imran Q.","date":"Jan 2026","text":"Traditional and authentic, exactly what we hoped for.","reliability":"none","flag":null}]'::jsonb),
  ('8a2f1b10-0008-4a3e-9c2d-1a2b3c4d5e08', 'dhun', 'Dhun Sangam Orchestra', 'Delhi NCR', ARRAY['orchestra']::text[], ARRAY[]::text[], '16-piece orchestra · film songs, live strings', null, 16, 4.5, false, 190000, '{"performance":190000,"extraHour":28000,"sound":28000,"travelCity":8000,"outstation":35000,"earlySetup":10000,"dj":22000,"advancePct":55,"refundDays":0,"contract":false}'::jsonb, ARRAY['2026-11-28']::date[], '[{"author":"Suresh & Kamala","date":"Feb 2026","text":"They did not arrive. No call, no message. We ran the reception on a phone playlist and never saw the advance again.","reliability":"negative","flag":"no-show"},{"author":"Priya M.","date":"Feb 2026","text":"Sixteen musicians on stage is a real spectacle.","reliability":"none","flag":null},{"author":"Hemant R.","date":"Jan 2026","text":"String section was gorgeous.","reliability":"none","flag":null},{"author":"Bhavna S.","date":"Jan 2026","text":"Started an hour late but played beautifully once they did.","reliability":"negative","flag":null},{"author":"Lalit K.","date":"Dec 2025","text":"Impressive scale for the price.","reliability":"none","flag":null},{"author":"Reema J.","date":"Dec 2025","text":"Guests were amazed.","reliability":"none","flag":null},{"author":"Om Prakash T.","date":"Nov 2025","text":"Very grand, good for a large venue.","reliability":"none","flag":null}]'::jsonb)
